import{_ as t,o as r,c as a,a2 as o}from"./chunks/framework.BZO4qERu.js";const p=JSON.parse('{"title":"Preferences","description":"","frontmatter":{},"headers":[],"relativePath":"guides/preferences.md","filePath":"guides/preferences.md","lastUpdated":1790952322000}'),d={name:"guides/preferences.md"};function s(n,e,i,h,c,l){return r(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="preferences" tabindex="-1">Preferences <a class="header-anchor" href="#preferences" aria-label="Permalink to &quot;Preferences&quot;">​</a></h1><p>Memoh v0.13 includes user-level preferences for the client. These preferences change how the interface looks and how keyboard shortcuts behave for the current device profile. They do not change a bot&#39;s personality, model, tools, memory, or access rules.</p><p>Open <strong>Settings</strong>, then use <strong>Appearance</strong> for visual preferences and <strong>Keyboard</strong> for shortcuts.</p><hr><h2 id="appearance" tabindex="-1">Appearance <a class="header-anchor" href="#appearance" aria-label="Permalink to &quot;Appearance&quot;">​</a></h2><p>The <strong>Appearance</strong> page is split into interface, typography, code highlighting, and diagram settings. Changes apply immediately.</p><h3 id="interface" tabindex="-1">Interface <a class="header-anchor" href="#interface" aria-label="Permalink to &quot;Interface&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Setting</th><th>What It Does</th></tr></thead><tbody><tr><td><strong>Language</strong></td><td>Sets the interface language. v0.13 includes English, Simplified Chinese, and Japanese. If you have not chosen a language yet, Memoh detects English, Chinese, or Japanese from the browser language and falls back to English.</td></tr><tr><td><strong>Theme</strong></td><td>Chooses Light, Dark, or System. System follows the operating system or browser color mode.</td></tr><tr><td><strong>Color Scheme</strong></td><td>Changes the accent palette used by brand elements, status colors, and interface controls. Available schemes are Memoh, Ocean, Forest, Rose, and Amber.</td></tr></tbody></table><p>Language is for the Memoh interface. A bot&#39;s reply language is still configured from the bot settings.</p><h3 id="typography" tabindex="-1">Typography <a class="header-anchor" href="#typography" aria-label="Permalink to &quot;Typography&quot;">​</a></h3><p>Use typography settings when the interface feels too small, too large, or when you prefer a different code font.</p><table tabindex="0"><thead><tr><th>Setting</th><th>What It Affects</th><th>Range / Default</th></tr></thead><tbody><tr><td><strong>UI Font Size</strong></td><td>General interface text and controls</td><td><code>12</code>-<code>20</code> px, default <code>16</code></td></tr><tr><td><strong>Code Font Size</strong></td><td>Code editors, Markdown code blocks, and terminal text</td><td><code>11</code>-<code>20</code> px, default <code>13</code></td></tr><tr><td><strong>UI Font Family</strong></td><td>The main interface font</td><td>Default: <code>system-ui, sans-serif</code></td></tr><tr><td><strong>Code Font Family</strong></td><td>Code, editor, and terminal font stack</td><td>Default: <code>ui-monospace, monospace</code></td></tr></tbody></table><p>Font family fields accept normal CSS-style font stacks, such as <code>Inter, system-ui, sans-serif</code> or <code>&quot;JetBrains Mono&quot;, ui-monospace, monospace</code>. The font must be available on your device or browser environment. Clear the field, or enter the default value, to return to Memoh&#39;s default stack.</p><h3 id="code-highlighting" tabindex="-1">Code Highlighting <a class="header-anchor" href="#code-highlighting" aria-label="Permalink to &quot;Code Highlighting&quot;">​</a></h3><p>Memoh uses Shiki themes for highlighted code. You can choose separate themes for light mode and dark mode:</p><table tabindex="0"><thead><tr><th>Setting</th><th>What It Affects</th></tr></thead><tbody><tr><td><strong>Light theme</strong></td><td>Code blocks and editors while the interface is in light mode</td></tr><tr><td><strong>Dark theme</strong></td><td>Code blocks and editors while the interface is in dark mode</td></tr></tbody></table><p>The theme picker searches the bundled Shiki theme list and shows a live preview, so you can compare the light and dark choices before leaving the page.</p><h3 id="diagrams" tabindex="-1">Diagrams <a class="header-anchor" href="#diagrams" aria-label="Permalink to &quot;Diagrams&quot;">​</a></h3><p>Mermaid diagrams rendered in chat and Markdown previews use the <strong>Mermaid Theme</strong> preference.</p><table tabindex="0"><thead><tr><th>Theme</th><th>Behavior</th></tr></thead><tbody><tr><td><strong>Auto</strong></td><td>Matches the current interface mode.</td></tr><tr><td><strong>Default</strong></td><td>Uses Mermaid&#39;s default light theme.</td></tr><tr><td><strong>Dark</strong></td><td>Uses Mermaid&#39;s dark theme.</td></tr><tr><td><strong>Forest</strong></td><td>Uses Mermaid&#39;s forest theme.</td></tr><tr><td><strong>Neutral</strong></td><td>Uses Mermaid&#39;s neutral theme.</td></tr></tbody></table><p>Diagrams that already include their own Mermaid initialization directive may keep their authored theme, which is useful for documents that need a specific diagram style.</p><hr><h2 id="keyboard-shortcuts" tabindex="-1">Keyboard Shortcuts <a class="header-anchor" href="#keyboard-shortcuts" aria-label="Permalink to &quot;Keyboard Shortcuts&quot;">​</a></h2><p>The <strong>Keyboard</strong> page lists editable shortcuts by scope. Click <strong>Edit</strong> on a row, press the new key combination, then save.</p><h3 id="default-shortcuts" tabindex="-1">Default Shortcuts <a class="header-anchor" href="#default-shortcuts" aria-label="Permalink to &quot;Default Shortcuts&quot;">​</a></h3><p><code>Cmd</code> on macOS is shown as <code>Ctrl</code> on Windows and Linux.</p><table tabindex="0"><thead><tr><th>Action</th><th>Default</th><th>Scope</th></tr></thead><tbody><tr><td>Close current workspace tab</td><td><code>Cmd/Ctrl + W</code> in the desktop app. In a normal browser, the browser keeps its native close-tab behavior.</td><td>Global</td></tr><tr><td>Save active file</td><td><code>Cmd/Ctrl + S</code></td><td>Global</td></tr><tr><td>Toggle sidebar</td><td><code>Cmd/Ctrl + B</code></td><td>Global</td></tr><tr><td>Open Settings</td><td><code>Cmd/Ctrl + K</code></td><td>Global</td></tr><tr><td>Close media lightbox</td><td><code>Esc</code></td><td>Media Lightbox</td></tr><tr><td>Previous media</td><td><code>Left Arrow</code></td><td>Media Lightbox</td></tr><tr><td>Next media</td><td><code>Right Arrow</code></td><td>Media Lightbox</td></tr></tbody></table><p>Global shortcuts are active across the app. Media Lightbox shortcuts are active only while the media preview overlay is open.</p><h3 id="editing-rules" tabindex="-1">Editing Rules <a class="header-anchor" href="#editing-rules" aria-label="Permalink to &quot;Editing Rules&quot;">​</a></h3><p>Memoh checks a shortcut before saving it:</p><ul><li><code>Cmd/Ctrl + W</code>, <code>Cmd/Ctrl + Q</code>, <code>Cmd/Ctrl + T</code>, and <code>Cmd/Ctrl + N</code> are reserved for the browser or operating system.</li><li>Global shortcuts must include <code>Cmd/Ctrl</code> or <code>Alt</code>, so normal typing does not trigger app commands.</li><li>Two shortcuts in the same scope cannot use the same combination.</li><li>A shortcut may share a combination with a different scope, but Memoh shows a warning because only the active scope can use it.</li></ul><p>Use the reset button on a row to restore one shortcut. Use <strong>Reset all</strong> to clear every custom shortcut.</p><hr><h2 id="a-few-practical-notes" tabindex="-1">A Few Practical Notes <a class="header-anchor" href="#a-few-practical-notes" aria-label="Permalink to &quot;A Few Practical Notes&quot;">​</a></h2><ul><li>Appearance and keyboard preferences are personal UI preferences. Other users and bots are not changed.</li><li>Preferences are stored on the current device/browser profile, so another browser or machine may need its own setup.</li><li>If the interface looks wrong after experimenting with fonts or shortcuts, reset the changed field or shortcut from the same page.</li></ul>',35)])])}const m=t(d,[["render",s]]);export{p as __pageData,m as default};
